SELECT array_to_string(array_agg(t.pid), ',') AS id, purchase_org_name, supplier_name, images_url, sku_no, productName, spu_no, avg(tax_price) AS tax_price, round(SUM(orderAmount) / COUNT(t.id)::numeric ,4) AS avgPrice, COUNT(t.id) AS orderQty, SUM(orderAmount) AS orderAmount, max(createTime) AS createTime FROM ( SELECT pod.id AS pid, po.purchase_org_name, pos.supplier_name, pd.images_url, pod.sku_no, pd."name" AS productName, pi.spu_no, pod.tax_price AS tax_price, po.id AS id, pod.purchase_amount AS orderAmount, po.create_time AS createTime, po.purchase_date FROM purchase_order_detail pod LEFT JOIN purchase_order po ON pod.purchase_order_id = po.id LEFT JOIN purchase_order_supplier pos ON pos.purchase_order_id = po.id LEFT JOIN product_detail pd ON pod.sku_id = pd.id LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE pod.is_deleted = FALSE AND po.is_deleted = FALSE AND pos.is_deleted = FALSE AND pd.is_deleted = FALSE AND pi.is_deleted = FALSE
AND po.purchase_date >= #{params.billDateList[0]} AND (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) >= po.purchase_date
AND pod.sku_no IN
#{item}
AND pi.id IN
#{item}
AND po.delivery_warehouse_id in
#{item}
AND po.purchase_org_id in
#{item}
AND pos.supplier_id in
#{item}
${params.permissionSql}
ORDER BY po.purchase_org_name, pos.supplier_name, po.create_time DESC )t GROUP BY purchase_org_name, supplier_name, images_url, sku_no, productName, spu_no

